mapper.select:
SELECT b.id, b.bill_no, b.bill_type, b.bill_month, b.bill_amount, b.payable_amount, b.transaction_status, b.create_time, b.payment_deadline, e.name AS elder_name FROM `bill` b LEFT JOIN elder e ON b.elder_id = e.id WHERE 1 = 1
AND b.transaction_status = #{transactionStatus}
AND b.elder_id = #{elderId}
ORDER BY b.create_time DESC

SELECT id, bill_no, trading_order_no, bill_type, bill_month, elder_id, bill_amount, payable_amount, prepaid_amount, deposit_amount, current_cost, payment_deadline, transaction_status, bill_start_time, bill_end_time, total_days, create_time, lname, type_name, update_time, create_by, update_by, remark FROM `bill` WHERE 1 = 1
AND transaction_status = #{transactionStatus}
AND elder_id = #{elderId}
ORDER BY create_time DESC

mapper.insert:
INSERT INTO prepaid_recharge_record (
    recharge_amount, recharge_voucher, recharge_method,
    elder_id, prepaid_recharge_no, remark, create_time, create_by
) VALUES (
    #{rechargeAmount}, #{rechargeVoucher}, #{rechargeMethod},
    #{elderId}, #{prepaidRechargeNo}, #{remark}, NOW(), #{createBy}
)
